css:
.loader {
  position: relative;
  width: 52px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 24px;
  height: 24px;
  margin: -12px 0 0 -12px;
  border-radius: 50%;
  background: #6366f1;
  box-shadow: inset -4px -4px 0 rgba(0, 0, 0, 0.18);
  z-index: 2;
}
.loader i:nth-child(1) {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 50px;
  height: 20px;
  margin: -10px 0 0 -25px;
  border: 4px solid #6366f1;
  border-radius: 50%;
  box-sizing: border-box;
  transform: rotate(-18deg);
  z-index: 1;
}
.loader i:nth-child(2) {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 44px;
  height: 44px;
  margin: -22px 0 0 -22px;
  z-index: 3;
  animation: spin 1.8s linear infinite;
}
.loader i:nth-child(2)::before {
  content: "";
  position: absolute;
  top: -3px;
  left: 50%;
  width: 7px;
  height: 7px;
  margin-left: -3.5px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes spin { to { transform: rotate(360deg); } }
